import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNITS[_n] = _secs

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT = re.compile(r"\s*(" + _NUM + r")\s*([a-zA-Z]+)\s*")
_ISO = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    if s[:1] in "Pp":
        m = _ISO.fullmatch(s.upper())
        if not m or not any(m.groups()) or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO duration: {text!r}")
        mults = (604800, 86400, 3600, 60, 1)
        total = sum(Decimal(g) * k for g, k in zip(m.groups(), mults) if g)
        return _round(total)

    # Clock notation
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(re.fullmatch(r"\d+", p) for p in parts[:-1]) or not re.fullmatch(_NUM, parts[-1]):
            raise ValueError(f"invalid clock duration: {text!r}")
        nums = [Decimal(p) for p in parts]
        if len(nums) == 2:
            nums.insert(0, Decimal(0))
        h, mi, se = nums
        if mi >= 60 or se >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(h * 3600 + mi * 60 + se)

    # Number+unit components
    pos = 0
    total = Decimal(0)
    found = False
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += Decimal(m.group(1)) * _UNITS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

